// <auto-generated />
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { HubConnection } from '@microsoft/signalr';
import { useApiService } from '../hooks/useApiService';
import { createLogsHubConnection, logsHubMethods, type LogsHubConnectionState, type LogsHubCallbacks } from './logsHub';

// Stops a connection once its start has settled (stopping during the negotiation fails the start)
async function stopWhenStarted(connection: HubConnection, start: Promise<void> | null): Promise<void> {
  await start?.catch(() => undefined);
  await connection.stop();
}

// The server a base URL is on: its origin, or '' (the page's) for a relative one - a hub's path is the server's,
// not the API's
function serverUrlOf(baseUrl: string): string {
  return /^[a-z][a-z\d+.-]*:\/\/[^/?#]+/i.exec(baseUrl)?.[0] ?? '';
}

export function useLogsHub(callbacks: LogsHubCallbacks) {
  const api = useApiService();
  const [connectionState, setConnectionState] = useState<LogsHubConnectionState>('Disconnected');
  const connectionRef = useRef<HubConnection | null>(null);
  const startRef = useRef<Promise<void> | null>(null);
  const callbacksRef = useRef(callbacks);
  callbacksRef.current = callbacks;

  const isConnected = connectionState === 'Connected';

  const connect = useCallback(async () => {
    if (connectionRef.current) return;

    setConnectionState('Connecting');
    const connection = createLogsHubConnection(serverUrlOf(api.baseUrl), () => callbacksRef.current);

    // Only the current connection updates the state: one that was replaced or stopped is history, and a
    // closed one is let go of so connect() starts a new one
    const isCurrent = () => connectionRef.current === connection;
    connection.onreconnecting(() => {
      if (isCurrent()) setConnectionState('Reconnecting');
    });
    connection.onreconnected(() => {
      if (isCurrent()) setConnectionState('Connected');
    });
    connection.onclose(() => {
      if (!isCurrent()) return;
      connectionRef.current = null;
      setConnectionState('Disconnected');
    });

    connectionRef.current = connection;
    const start = connection.start();
    startRef.current = start;
    try {
      await start;
      if (isCurrent()) setConnectionState('Connected');
    } catch {
      if (isCurrent()) {
        connectionRef.current = null;
        setConnectionState('Disconnected');
      }
    }
  }, [api]);

  const disconnect = useCallback(async () => {
    const connection = connectionRef.current;
    if (!connection) return;

    connectionRef.current = null;
    try {
      await stopWhenStarted(connection, startRef.current);
    } finally {
      setConnectionState('Disconnected');
    }
  }, []);

  useEffect(() => {
    return () => {
      const connection = connectionRef.current;
      connectionRef.current = null;
      if (connection) {
        void stopWhenStarted(connection, startRef.current);
      }
    };
  }, []);

  const methods = useMemo(
    () => logsHubMethods({
      invoke: <T>(methodName: string, ...args: unknown[]): Promise<T> => {
        const connection = connectionRef.current;
        return connection ? connection.invoke<T>(methodName, ...args) : Promise.reject(new Error('The logs hub is not connected'));
      },
    }),
    [],
  );

  return { connectionState, isConnected, connect, disconnect, methods };
}